import abc

from openpyxl.styles import Alignment, Font


class ExcelSetCell(object):
    __metaclass__ = abc.ABCMeta

    @staticmethod
    def fill_cell(cell, value, bold=False, italic=False, size='11', horizontal='left', vertical='bottom', wrap_text=False, text_rotation=0,
                  number_format=None, hyperlink=None):
        """
        Method set value and format cells in Excel file
        :param cell: put location cell in sheet
        :param value: set value cell
        :param bold: set bold, default False
        :param italic: set italic, default False
        :param size: set bold, default 11
        :param horizontal: set horizontal, default left
        :param vertical: set vertical, default bottom
        :param wrap_text: set wrap_text, default False
        :param text_rotation: set text_rotation, default 0
        :param number_format: set number_format, default
        :param hyperlink: set hyperlink, default
        :return:
        """
        try:
            cell.value = value.encode('utf-8')
        except AttributeError:
            cell.value = value
        cell.font = Font(bold=bold, italic=italic, size=size)
        cell.alignment = Alignment(horizontal=horizontal, vertical=vertical, text_rotation=text_rotation, wrap_text=wrap_text)
        if number_format is not None:
            cell.number_format = number_format
        if hyperlink is not None:
            cell.hyperlink = hyperlink
